const items = $input.all();

function num(v) {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
}
function boolOrNull(v) { return (v === true || v === false) ? v : null; }

function build(p, h, raw) {
  const profile = { platform: p, handle: h, nickname: null, follower_count: null,
    following_count: null, post_count: null, avg_engagement: null, bio: null,
    is_verified: null, category: null, profile_image_url: null };
  try {
    if (p === 'instagram') {
      const u = (raw.data && raw.data.user) || raw.user || {};
      profile.nickname = u.full_name || u.username || null;
      profile.follower_count = num(u.edge_followed_by && u.edge_followed_by.count);
      profile.following_count = num(u.edge_follow && u.edge_follow.count);
      profile.post_count = num(u.edge_owner_to_timeline_media && u.edge_owner_to_timeline_media.count);
      if (profile.post_count === null) profile.post_count = num(u.edge_felix_video_timeline && u.edge_felix_video_timeline.count);
      profile.bio = u.biography || null;
      profile.is_verified = boolOrNull(u.is_verified);
      profile.category = u.category_name || null;
      profile.profile_image_url = u.profile_pic_url_hd || u.profile_pic_url || null;
      const edges = (u.edge_felix_video_timeline && u.edge_felix_video_timeline.edges) || [];
      const likes = edges.map(e => {
        const n = e && e.node;
        return num(n && ((n.edge_media_preview_like && n.edge_media_preview_like.count) || (n.edge_liked_by && n.edge_liked_by.count)));
      }).filter(x => x !== null && x > 0);
      if (likes.length > 0) profile.avg_engagement = Math.round(likes.reduce((a, b) => a + b, 0) / likes.length);
    } else if (p === 'tiktok') {
      const u = raw.user || {};
      const st = raw.statsV2 || raw.stats || {};
      profile.nickname = u.nickname || u.uniqueId || null;
      profile.follower_count = num(st.followerCount);
      profile.following_count = num(st.followingCount);
      profile.post_count = num(st.videoCount);
      profile.bio = u.signature || null;
      profile.is_verified = boolOrNull(u.verified);
      profile.profile_image_url = u.avatarLarger || u.avatarMedium || null;
      const vc = profile.post_count;
      const heart = num(st.heart) || num(st.heartCount);
      if (vc && heart) profile.avg_engagement = Math.round(heart / vc);
    } else if (p === 'youtube') {
      const c = raw.channel || raw.data || raw;
      profile.nickname = c.title || c.name || null;
      profile.follower_count = num(c.subscriberCount) || num(c.subscriber_count);
      profile.post_count = num(c.videoCount) || num(c.video_count);
      profile.bio = c.description || null;
      profile.is_verified = boolOrNull(c.isVerified);
      profile.category = c.category || c.categoryName || null;
      const th = (c.thumbnails && c.thumbnails[0] && c.thumbnails[0].url) || c.thumbnail || null;
      profile.profile_image_url = th;
    } else if (p === 'twitter') {
      const c = raw.profile || (raw.data && raw.data.user) || raw.data || raw;
      profile.nickname = c.name || c.full_name || null;
      profile.follower_count = num(c.followers_count) || num(c.followersCount);
      profile.following_count = num(c.friends_count) || num(c.following_count);
      profile.post_count = num(c.statuses_count) || num(c.tweet_count);
      profile.bio = c.description || null;
      profile.is_verified = boolOrNull(c.verified);
      profile.category = c.category || null;
      profile.profile_image_url = c.profile_image_url_https || c.profile_image_url || c.avatar || null;
    }
  } catch (e) { /* keep nulls */ }
  return profile;
}

const out = [];
for (const it of items) {
  const raw = it.json.raw || {};
  const platform = it.json.platform;
  const handle = it.json.handle;
  const meta = { platform, credits_charged: num(raw.credits_charged), credits_remaining: num(raw.credits_remaining) };
  if (raw.account_deactivated) {
    out.push({ json: { ok: false, error: 'account_deactivated', message: raw.message || "Account doesn't exist", profile: null, meta } });
  } else if (raw.success === false || num(raw.statusCode) === 402) {
    const status = num(raw.statusCode);
    out.push({ json: { ok: false, error: status === 402 ? 'low_credits' : 'api_error', status, message: raw.message || 'API error', profile: null, meta } });
  } else {
    out.push({ json: { ok: true, profile: build(platform, handle, raw), meta } });
  }
}
return out;

const wb = ($json.body && typeof $json.body === 'object') ? $json.body : $json;
const handle = (typeof wb.handle === 'string') ? wb.handle.trim() : '';
const platform = (typeof wb.platform === 'string') ? wb.platform.trim().toLowerCase() : '';
if (!handle) return [{ json: { ok: false, error: 'handle is required' } }];
if (!['instagram', 'youtube', 'tiktok', 'twitter'].includes(platform)) {
  return [{ json: { ok: false, error: 'unsupported platform: ' + (platform || 'unknown') } }];
}
return [{ json: { ok: true, handle, platform } }];

